script:
import { readFileSync, writeFileSync } from 'node:fs';

const currency = 'CNY';
const reportTag = '春季观察';
const title = '双月汇总';
const multiplier = 2;
const expectedBimonthlyTotal = 720;
const expectedCheckCode = 735;

function parseCsv(text) {
  const lines = text.trim().split(/\r?\n/);
  const headers = lines.shift().split(',');
  return lines.filter(Boolean).map((line) => {
    const values = line.split(',');
    return Object.fromEntries(headers.map((h, i) => [h, values[i]]));
  });
}

function formatNumber(value) {
  return Number.isInteger(value) ? String(value) : value.toFixed(2);
}

const rows = parseCsv(readFileSync('sales.csv', 'utf8'));
if (!rows.length) throw new Error('sales.csv 没有数据行');

const monthly = new Map();
let rawTotal = 0;
for (const row of rows) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(row.date)) throw new Error(`无效日期: ${row.date}`);
  const amount = Number(row.amount);
  if (!Number.isFinite(amount)) throw new Error(`无效金额: ${row.amount}`);
  const month = row.date.slice(0, 7);
  rawTotal += amount;
  monthly.set(month, (monthly.get(month) ?? 0) + amount);
}

const summary = Array.from(monthly.entries())
  .sort(([a], [b]) => a.localeCompare(b))
  .map(([month, rawAmount], index, arr) => {
    const amountCny = rawAmount * multiplier;
    const prev = index > 0 ? arr[index - 1][1] * multiplier : null;
    const mom = prev === null || prev === 0 ? null : (amountCny - prev) / prev;
    return { month, amount_cny: amountCny, mom };
  });

const doubledTotal = rawTotal * multiplier;
if (doubledTotal !== expectedBimonthlyTotal) {
  throw new Error(`双月合计校验失败: expected ${expectedBimonthlyTotal}, got ${doubledTotal}`);
}
const checkCode = expectedBimonthlyTotal + 15;
if (checkCode !== expectedCheckCode) {
  throw new Error(`校验码失败: expected ${expectedCheckCode}, got ${checkCode}`);
}

const csv = [
  'report_tag,currency,month,amount_cny,mom',
  ...summary.map((r) => [
    reportTag,
    currency,
    r.month,
    formatNumber(r.amount_cny),
    r.mom === null ? '' : `${(r.mom * 100).toFixed(2)}%`,
  ].join(',')),
  [reportTag, currency, '双月合计', formatNumber(expectedBimonthlyTotal), ''].join(','),
  [reportTag, currency, '校验码', formatNumber(expectedCheckCode), ''].join(','),
].join('\n') + '\n';
writeFileSync('monthly_summary.csv', csv);

const report = `# ${title}\n\n- 报告标签：${reportTag}\n- 币种：${currency}\n- 口径：sales.csv 原始金额在展示及 CSV 中统一乘以 ${multiplier}\n- 数据行数：${rows.length}\n- 日期范围：${rows.map((r) => r.date).sort()[0]} 至 ${rows.map((r) => r.date).sort().at(-1)}\n\n## 月度汇总\n\n| 月份 | 金额（${currency}，已乘以 ${multiplier}） | MoM |\n|---|---:|---:|\n${summary.map((r) => `| ${r.month} | ${formatNumber(r.amount_cny)} | ${r.mom === null ? 'N/A' : `${(r.mom * 100).toFixed(2)}%`} |`).join('\n')}\n\n## 补充要求落实\n\n- 双月合计：${expectedBimonthlyTotal}\n- 校验码：${expectedCheckCode}\n- 报告标题已改为「${title}」\n- 保留报告标签「${reportTag}」与币种 ${currency}\n- reproduce.mjs 按上述新口径生成并核验 monthly_summary.csv 与 report.md\n\n## 数据质量与校验\n\n- 输入文件：sales.csv\n- 金额字段均可解析为数值。\n- 月度汇总基于 date 字段的 YYYY-MM。\n- 首月 MoM 无前月基准，记为 N/A。\n`;
writeFileSync('report.md', report);

console.log(JSON.stringify({
  status: 'ok',
  rows: rows.length,
  months: summary.length,
  currency,
  reportTag,
  title,
  multiplier,
  bimonthlyTotal: expectedBimonthlyTotal,
  checkCode,
}, null, 2));
